def transform(g):
    from collections import Counter
    c=Counter(v for r in g for v in r)
    order=[v for v,_ in c.most_common()]
    bg=order[1]          # second-most-common = background to stamp on
    mino=order[-1]       # rarest = sprite color
    pts=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v==mino]
    r0,c0=min(p[0] for p in pts),min(p[1] for p in pts)
    shape={(p[0]-r0,p[1]-c0) for p in pts}
    h=max(p[0] for p in pts)-r0+1; w=max(p[1] for p in pts)-c0+1
    out=[r[:] for r in g]; H,W=len(g),len(g[0])
    for i in range(H-h+1):
        for j in range(W-w+1):
            if all(g[i+a][j+b]==bg for a,b in shape):
                for a,b in shape: out[i+a][j+b]=mino
    return out
